<div class="d-flex justify-content-between mb-3"><div><h4 class="mb-0">Price history</h4><div class="text-muted"><?= e($p['sku'] . ' - ' . $p['name']) ?></div></div><a class="btn btn-outline-secondary align-self-start" href="javascript:history.back()">Back</a></div>
<div class="card"><table class="table table-sm mb-0"><thead class="table-light"><tr><th>When</th><th>Field</th><th class="text-end">Old</th><th class="text-end">New</th><th>By</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['changed_at']) ?></td><td><?= e(ucwords(str_replace('_', ' ', $r['field_name']))) ?></td><td class="text-end"><?= $r['old_value'] !== null ? number_format($r['old_value'], 2) : '-' ?></td><td class="text-end"><?= $r['new_value'] !== null ? number_format($r['new_value'], 2) : '-' ?></td><td><?= e($r['username']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="5" class="text-center text-muted py-3">No changes recorded.</td></tr><?php endif; ?></tbody></table></div>
